-- A `float8` after an `int4` is aligned to 8 as an `int8` is, leaving a 4-byte hole: `(int4,
-- float8, text)` holds 2 676 characters. `btree_float8_after_int4_over_limit_loud` is one more.
-- @setup
CREATE TABLE t (a int4, b float8, c text);
CREATE INDEX t_i ON t (a, b, c);
INSERT INTO t VALUES (1, 1, '');
-- @test
-- @profile-lock
SELECT count(*) FROM t;
